\longrightarrow
\text{inclusión y operaciones}
\longrightarrow
\text{pares ordenados}
\longrightarrow
\text{productos cartesianos}
\longrightarrow
\text{relaciones}
\longrightarrow
\text{equivalencias y cocientes}
